import assert from "node:assert/strict";
import { test } from "node:test";
import {
  compareFingerprints,
  hashDistance,
  hashGrayscale,
  isImageMatch,
} from "../src/sources/imageHash.ts";
import type { ImageFingerprint } from "../src/sources/imageHash.ts";

test("pHash agrees with Python ImageHash 4.3.2 on identical grayscale samples", () => {
  // Reference values generated by ImageHash + Pillow + SciPy, independently of this port.
  const references = [
    [1, "c994515ec1ed78a3"],
    [7, "a18ed3ef759c0342"],
    [42, "b1dd2595e94843d6"],
  ] as const;
  for (const [seed, expected] of references) {
    let state: number = seed;
    const pixels = Uint8Array.from({ length: 1024 }, () => {
      state = (Math.imul(1664525, state) + 1013904223) >>> 0;
      return state >>> 24;
    });
    assert.equal(hashGrayscale(pixels), expected);
  }
});

test("translated Nagisa preserves matching regions despite larger differences in text regions", () => {
  // Captured with Chrome's software Canvas from the two compressed source images.
  const fingerprint = (hashes: string[]): ImageFingerprint => ({
    version: "reference-experiment-v1",
    width: 407,
    height: 540,
    whole: hashes[0],
    regions: hashes.slice(1).map((hash) => ({ hash, contrast: 30 })),
  });
  const original = fingerprint([
    "e7aef45283289a9c",
    "e195ca969cac8b95",
    "eaa883c3a4cdfa19",
    "a6d9f8cec922cc19",
    "f9f83a4962c9cc4c",
    "f65ca4a1c74bb8e0",
    "b7a7a4da348d9264",
    "ce7ba5c62aa52662",
    "a7c4b1c33eb261c9",
    "cd2634b23fbe60a1",
  ]);
  const translated = fingerprint([
    "e7aeb44083ac9adc",
    "e39e8e56942e9315",
    "eaed83c3a4cdc819",
    "a6d978cec922ce19",
    "f9e1ca1a46ccad1c",
    "fe5ca4a1c74bb8a0",
    "b6a6e4c8368d8e71",
    "ce7b24c2aaa537c2",
    "a7c4b1c33cb271c9",
    "dd2234b23fbe60a1",
  ]);
  const comparison = compareFingerprints(
    original,
    translated,
    12,
    "reference-experiment-v1",
  );
  assert.equal(comparison.wholeDistance, 6);
  assert.deepEqual(comparison.regionDistances, [14, 6, 2, 20, 2, 12, 8, 2, 2]);
  assert.equal(comparison.medianRegionDistance, 6);
  assert.equal(comparison.informativeRegionCount, 9);
  assert.equal(isImageMatch(comparison), true);
  assert.equal(isImageMatch({ ...comparison, wholeDistance: 10 }), false);
  assert.equal(
    isImageMatch({
      ...comparison,
      regionDistances: [2, 2, 2, 2, 2, 2, 20, 20, 20],
    }),
    false,
  );
  assert.equal(
    isImageMatch({ ...comparison, aspectRatioDifference: 0.1 }),
    false,
  );
  const blank = {
    ...original,
    regions: original.regions.map((region) => ({ ...region, contrast: 0 })),
  };
  assert.equal(
    compareFingerprints(original, blank, 12, "reference-experiment-v1")
      .informativeRegionCount,
    0,
  );
  assert.equal(
    compareFingerprints(original, blank, 12, "reference-experiment-v1")
      .medianRegionDistance,
    null,
  );
  assert.throws(() =>
    compareFingerprints(
      original,
      { ...translated, regions: [] },
      12,
      "reference-experiment-v1",
    ),
  );
});

test("Hamming distance handles all 64 bits and rejects invalid input", () => {
  assert.equal(hashDistance("e7aeb45883a89a9c", "e7aeb44083acda9c"), 4);
  assert.equal(hashDistance("8000000000000000", "0000000000000000"), 1);
  assert.equal(hashDistance("ffffffffffffffff", "0000000000000000"), 64);
  assert.equal(hashDistance("E7AEB45883A89A9C", "e7aeb45883a89a9c"), 0);
  assert.throws(() => hashDistance("invalid", "0000000000000000"));
  assert.throws(() => hashGrayscale(new Uint8Array(1)));
  assert.throws(() => hashGrayscale(new Float64Array(1024).fill(NaN)));
});
